function selectedMapWorld(context:SharedContext){const requested=new URLSearchParams(context.location.search).get("world")==="tree"?"tree":"palpagos";return context.mapData?.worlds?.find(world=>world.id===requested)||context.mapData?.worlds?.[0]||null}
